// Generated by tools/tokens from tokens/prism.resolver.json and brands/*/brand.json. Do not edit; run `pnpm tokens:build`.

/// The repo brands (ADR-0020 §7): one case per `brand` context of the resolver, every one shipped in DSTokens.
/// `DSTheme(brand:)` sets `DSTokenContext.brand` once per scene; components read brand values through `DSTokenSet`.
public enum DSBrand: String, CaseIterable, Hashable, Sendable {
    /// Prism reference brand
    case prism = "prism"
    /// Prism reference brand, Native font preset
    case prismNative = "prism-native"

    /// The resolver's default brand.
    public static let `default`: DSBrand = .prism

    /// The `preset` label of brand.json (ADR-0020 §5).
    public var preset: DSFontPreset {
        switch self {
        case .prism: .signature
        case .prismNative: .native
        }
    }

    /// The colorset namespace folder in Colors.xcassets (ADR-0020 §7): a brand whose colorsets are byte-identical to
    /// an earlier brand's shares its folder.
    public var colorNamespace: String {
        switch self {
        case .prism, .prismNative: "prism"
        }
    }

    /// The face of each font slot (ADR-0020 §5, ADR-0021 §9): a family bundled in DSTokens, or a system design
    /// (system-ui → .default, ui-rounded → .rounded, ui-monospace → .monospaced, ui-serif → .serif).
    public var faces: [DSFontSlot: DSFontFace] {
        switch self {
        case .prism:
            return [
                .display: DSFontFace(families: ["Onest"], file: "onest/Onest[wght].ttf", postScriptNames: [100: "Onest-Thin", 200: "Onest-ExtraLight", 300: "Onest-Light", 400: "Onest-Regular", 500: "Onest-Medium", 600: "Onest-SemiBold", 700: "Onest-Bold", 800: "Onest-ExtraBold", 900: "Onest-Black"], opticalSize: nil, system: nil),
                .mono: DSFontFace(families: ["JetBrains Mono"], file: "jetbrains-mono/JetBrainsMono[wght].ttf", postScriptNames: [100: "JetBrainsMonoRoman-Thin", 200: "JetBrainsMonoRoman-ExtraLight", 300: "JetBrainsMonoRoman-Light", 400: "JetBrainsMono-Regular", 500: "JetBrainsMonoRoman-Medium", 700: "JetBrainsMonoRoman-Bold", 800: "JetBrainsMonoRoman-ExtraBold"], opticalSize: nil, system: nil),
                .ui: DSFontFace(families: ["Onest"], file: "onest/Onest[wght].ttf", postScriptNames: [100: "Onest-Thin", 200: "Onest-ExtraLight", 300: "Onest-Light", 400: "Onest-Regular", 500: "Onest-Medium", 600: "Onest-SemiBold", 700: "Onest-Bold", 800: "Onest-ExtraBold", 900: "Onest-Black"], opticalSize: nil, system: nil),
            ]
        case .prismNative:
            return [
                .display: DSFontFace(families: ["system-ui"], file: nil, postScriptNames: [:], opticalSize: nil, system: .`default`),
                .mono: DSFontFace(families: ["ui-monospace"], file: nil, postScriptNames: [:], opticalSize: nil, system: .monospaced),
                .ui: DSFontFace(families: ["system-ui"], file: nil, postScriptNames: [:], opticalSize: nil, system: .`default`),
            ]
        }
    }
}
